public static int calculateTimeNeeded(int N) {
    if (N <= 1) {
        return 0;
    }
    if (N % 2 == 0) {
        int half = N / 2;
        return half * (half - 1);
    } else {
        int half = (N - 1) / 2;
        return half * half;
    }
}

