private void backtrack(int[] nums, boolean[] used, java.util.ArrayList<Integer> current, java.util.List<java.util.List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new java.util.ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, res);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    permuteHelper(nums, 0, res);
    return res;
}

private void permuteHelper(int[] nums, int index, List<List<Integer>> res) {
    if (index == nums.length) {
        List<Integer> perm = new ArrayList<>();
        for (int num : nums) {
            perm.add(num);
        }
        res.add(perm);
        return;
    }
    for (int i = index; i < nums.length; i++) {
        int tmp = nums[index];
        nums[index] = nums[i];
        nums[i] = tmp;
        permuteHelper(nums, index + 1, res);
        tmp = nums[index];
        nums[index] = nums[i];
        nums[i] = tmp;
    }
}

