public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int numStrings = strings.size();
    String first = strings.get(0);
    int minLen = first.length();
    for (int i = 1; i < numStrings; i++) {
        minLen = Math.min(minLen, strings.get(i).length());
    }
    for (int len = minLen; len >= 1; len--) {
        String base = first;
        int baseLen = base.length();
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i + len <= baseLen; i++) {
            String sub = base.substring(i, i + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        for (String cand : candidates) {
            String revCand = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (int idx = 0; idx < numStrings; idx++) {
                String s = strings.get(idx);
                if (!(s.contains(cand) || s.contains(revCand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) return 0;
    // Find the minimum length among all strings to set upper bound
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) return 0;
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) return 0;

    int low = 1, high = minLen, best = 0;
    while (low <= high) {
        int mid = (low + high) >>> 1;
        if (existsCommonCanonical(strings, mid)) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return best;
}

private boolean existsCommonCanonical(List<String> strings, int len) {
    HashSet<String> common = null;
    for (String s : strings) {
        HashSet<String> subs = new HashSet<>();
        for (int i = 0; i <= s.length() - len; i++) {
            String sub = s.substring(i, i + len);
            String rev = new StringBuilder(sub).reverse().toString();
            String canon = sub.compareTo(rev) <= 0 ? sub : rev;
            subs.add(canon);
        }
        if (common == null) {
            common = subs;
        } else {
            common.retainAll(subs);
            if (common.isEmpty()) return false;
        }
    }
    return common != null && !common.isEmpty();
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to generate candidate substrings
    String minStr = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        int len = s.length();
        if (len < minLen) {
            minLen = len;
            minStr = s;
        }
    }

    if (minStr == null || minLen == 0) {
        return 0;
    }

    // Helper to reverse a string
    java.util.function.Function<String, String> reverse = str -> {
        char[] arr = str.toCharArray();
        int i = 0, j = arr.length - 1;
        while (i < j) {
            char tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
            i++;
            j--;
        }
        return new String(arr);
    };

    // Iterate over all possible lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        for (int start = 0; start + len <= minLen; start++) {
            String sub = minStr.substring(start, start + len);
            String rev = reverse.apply(sub);
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }

    return 0;
}

public int findLargestSubstring(List<String> strings) {
