        return 0;
    }
    String first = strings.get(0);
    int n = first.length();
    java.util.Set<String> candidateSet = new java.util.HashSet<>();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String sub = first.substring(i, j);
            candidateSet.add(sub);
            candidateSet.add(new java.lang.StringBuilder(sub).reverse().toString());
        }
    }
    java.util.List<String> candidates = new java.util.ArrayList<>(candidateSet);
    candidates.sort((a, b) -> Integer.compare(b.length(), a.length()));
    for (String cand : candidates) {
        String rev = new java.lang.StringBuilder(cand).reverse().toString();
        boolean ok = true;
        for (String s : strings) {
            if (!s.contains(cand) && !s.contains(rev)) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return cand.length();
        }
    }
    return 0;
}

