    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }

    for (int len = minLen; len >= 1; len--) {
        // collect all substrings of length len from the first string
        java.util.Set<String> substrings = new java.util.HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            substrings.add(first.substring(i, i + len));
        }

        // check each candidate against all other strings
        for (String candidate : substrings) {
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String s = strings.get(idx);
                if (!(s.contains(candidate) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
