            }
        }
    }
    return 0; // no common substring found
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    int depositCount = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@') {
                depositCount++;
                // Depth-first search to mark all connected '@' cells
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                grid[r][c] = '*';
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            stack.push(new int[]{nr, nc});
                            grid[nr][nc] = '*';
                        }
                    }
                }
            }
        }
    }
    return depositCount;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int[][] visited = new int[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new int[grid[i].length];
    }
    int count = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && visited[r][c] == 0) {
                count++;
                dfs(grid, visited, r, c);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, int[][] visited, int r, int c) {
    int rows = grid.length;
    visited[r][c] = 1;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int k = 0; k < 8; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length
                && grid[nr][nc] == '@' && visited[nr][nc] == 0) {
            dfs(grid, visited, nr, nc);
        }
    }
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[grid[i].length];
    }
    int deposits = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (!visited[r][c] && grid[r][c] == '@') {
                deposits++;
                dfs(r, c, grid, visited);
            }
        }
    }
    return deposits;
}

private static void dfs(int r, int c, char[][] grid, boolean[][] visited) {
    visited[r][c] = true;
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) {
                continue;
            }
            int nr = r + dr;
            int nc = c + dc;
            if (nr < 0 || nr >= grid.length) {
                continue;
            }
            if (nc < 0 || nc >= grid[nr].length) {
                continue;
            }
            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                dfs(nr, nc, grid, visited);
            }
        }
    }
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    Deque<int[]> stack = new ArrayDeque<>();
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int x = pos[0];
                    int y = pos[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nx = x + dr[dir];
                        int ny = y + dc[dir];
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                                grid[nx][ny] == '@' && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            stack.push(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
    }
    return count;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int m = grid.length;
    int n = grid[0].length;
    boolean[][] visited = new boolean[m][n];
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};
    int deposits = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                deposits++;
                // Depth-first search to mark all connected '@'
                int[] stackX = new int[m * n];
                int[] stackY = new int[m * n];
                int top = 0;
                stackX[top] = i;
                stackY[top] = j;
                visited[i][j] = true;
                top++;

                while (top > 0) {
                    top--;
                    int x = stackX[top];
                    int y = stackY[top];
                    for (int d = 0; d < 8; d++) {
                        int nx = x + dx[d];
                        int ny = y + dy[d];
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                            grid[nx][ny] == '@' && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            stackX[top] = nx;
                            stackY[top] = ny;
                            top++;
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

public static int maxRegions(int N) {
    if (N <= 0) return 1; // no triangles, entire plane is one region
    long result = 3L * N * N - 3L * N + 2;
    return (int) result;
}

