public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) return "cannot be travelled";
    // Build adjacency list
    @SuppressWarnings("unchecked")
    ArrayList<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] p : paths) {
        if (p.length < 2) continue;
        int u = p[0];
        int v = p[1];
        if (u >= 0 && u < n && v >= 0 && v < n) {
            adj[u].add(v);
            adj[v].add(u);
        }
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }
    boolean[] visited = new boolean[n];
    ArrayDeque<Integer> queue = new ArrayDeque<>();
    queue.add(startNode);
    visited[startNode] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endNode) return "can be travelled";
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert a coordinate array to a single integer index
    java.util.function.IntSupplier indexFromCoords = () -> 0; // placeholder
    java.util.function.Function<int[], Integer> coordToIndex = coords -> {
        int index = 0;
        int power = 1;
        for (int k = 0; k < n; k++) {
            index += coords[k] * power;
            power *= n;
        }
        return index;
    };
    // Compute start and end indices
    int startIdx = coordToIndex.apply(start);
    int endIdx = coordToIndex.apply(end);
    if (startIdx == endIdx) return "can be travelled";

    // Build adjacency list
    java.util.Map<Integer, java.util.Set<Integer>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        int aIdx, bIdx;
        if (path.length == 2) { // indices provided directly
            aIdx = path[0];
            bIdx = path[1];
        } else { // coordinates provided (length = 2*n)
            int[] aCoords = new int[n];
            int[] bCoords = new int[n];
            for (int i = 0; i < n; i++) aCoords[i] = path[i];
            for (int i = 0; i < n; i++) bCoords[i] = path[n + i];
            aIdx = coordToIndex.apply(aCoords);
            bIdx = coordToIndex.apply(bCoords);
        }
        adj.computeIfAbsent(aIdx, k -> new java.util.HashSet<>()).add(bIdx);
        adj.computeIfAbsent(bIdx, k -> new java.util.HashSet<>()).add(aIdx);
    }

    // BFS to check reachability
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.offer(startIdx);
    visited.add(startIdx);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        java.util.Set<Integer> neighbors = adj.getOrDefault(cur, java.util.Collections.emptySet());
        for (int nxt : neighbors) {
            if (!visited.contains(nxt)) {
                if (nxt == endIdx) return "can be travelled";
                visited.add(nxt);
                queue.offer(nxt);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // Quick check if start equals end
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) return "can be travelled";

    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    // Ensure start and end nodes exist in the adjacency map
    adj.put(coordKey.apply(start), new java.util.ArrayList<>());
    adj.put(coordKey.apply(end), new java.util.ArrayList<>());

    // Build graph from paths
    for (int[] p : paths) {
        if (p == null || p.length != 2 * n) continue;
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(p, 0, a, 0, n);
        System.arraycopy(p, n, b, 0, n);
        String keyA = coordKey.apply(a);
        String keyB = coordKey.apply(b);
        adj.putIfAbsent(keyA, new java.util.ArrayList<>());
        adj.putIfAbsent(keyB, new java.util.ArrayList<>());
        adj.get(keyA).add(keyB);
        adj.get(keyB).add(keyA);
    }

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : adj.getOrDefault(current, java.util.Collections.emptyList())) {
            if (visited.contains(neighbor)) continue;
            if (neighbor.equals(endKey)) return "can be travelled";
            visited.add(neighbor);
            queue.offer(neighbor);
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
