    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        sb.append(coord[0]);
        for (int i = 1; i < coord.length; i++) {
            sb.append(',').append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // Edge case: start equals end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) {
            continue; // ignore malformed paths
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = coordToKey.apply(a);
        String bKey = coordToKey.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to find path
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (visited.contains(neighbor)) {
                continue;
            }
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(neighbor);
            queue.offer(neighbor);
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int[] f1 = new int[256];
    int[] f2 = new int[256];
    for (int i = 0; i < word1.length(); i++) {
        f1[word1.charAt(i)]++;
    }
    for (int i = 0; i < word2.length(); i++) {
        f2[word2.charAt(i)]++;
    }
    int common = 0;
    for (int i = 0; i < 256; i++) {
        common += Math.min(f1[i], f2[i]);
    }
    int numerator = 2 * common;
    int denominator = word1.length() + word2.length();
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int a = numerator, b = denominator;
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    int g = a;
    int numRed = numerator / g;
    int denRed = denominator / g;
    String value;
    if (denRed == 1) {
        value = Integer.toString(numRed);
    } else {
        value = numRed + "/" + denRed;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

public static String appx(String word1, String word2) {
    int count = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) >= 0) {
            count++;
        }
    }
    for (char c : word2.toCharArray()) {
        if (word1.indexOf(c) >= 0) {
            count++;
        }
    }
    int denom = word1.length() + word2.length();
    if (denom == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    if (count == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int g = gcd(count, denom);
    int num = count / g;
    int den = denom / g;
    String result;
    if (den == 1) {
        result = String.valueOf(num);
    } else {
        result = num + "/" + den;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

public static String appx(String word1, String word2) {
    // Create sets of unique characters for each word
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    Set<Character> set2 = new HashSet<>();
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }
    // Calculate distinct common letters
    Set<Character> intersection = new HashSet<>(set1);
    intersection.retainAll(set2);
    int commonDistinct = intersection.size();
    // Count common letters in both words (double count)
    int commonCount = 2 * commonDistinct;
    int denom = word1.length() + word2.length();

    // If no common letters, result is 0
    if (commonCount == 0) {
        return String.format("appx(%s, %s) = 0", word1, word2);
    }

    // Reduce the fraction
    int g = gcd(commonCount, denom);
    int num = commonCount / g;
    denom /= g;

    String result;
    if (denom == 1) {
        result = String.valueOf(num);
    } else {
        result = String.format("%d/%d", num, denom);
    }

    return String.format("appx(%s, %s) = %s", word1, word2, result);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

