public static String convertDatesToWeekdays(String date) {
    // Split the input date string
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in 'MM dd yyyy' format");
    }
    int month = Integer.parseInt(parts[0]); // 1-12
    int day = Integer.parseInt(parts[1]);   // 1-31
    int year = Integer.parseInt(parts[2]);  // e.g., 1997

    // Names of months and weekdays
    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String[] weekDayNames = {
        "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"
    };

    // Use Calendar to compute the weekday
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(java.util.Calendar.YEAR, year);
    cal.set(java.util.Calendar.MONTH, month - 1); // Calendar.MONTH is zero-based
    cal.set(java.util.Calendar.DAY_OF_MONTH, day);
    cal.set(java.util.Calendar.HOUR_OF_DAY, 0);
    cal.set(java.util.Calendar.MINUTE, 0);
    cal.set(java.util.Calendar.SECOND, 0);
    cal.set(java.util.Calendar.MILLISECOND, 0);

    int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1=Sunday, 7=Saturday
    String monthName = monthNames[month - 1];
    String weekDayName = weekDayNames[dayOfWeek - 1];

    return monthName + " " + day + ", " + year + " is a " + weekDayName;
}

