public boolean canArrange(int[] arr, int k) {
    // If array length is odd, cannot form n/2 pairs
    if (arr.length % 2 != 0) {
        return false;
    }

    java.util.Map<Integer, Integer> count = new java.util.HashMap<>();

    // Count remainders modulo k
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        count.put(rem, count.getOrDefault(rem, 0) + 1);
    }

    // Check pairing conditions
    for (java.util.Map.Entry<Integer, Integer> entry : count.entrySet()) {
        int rem = entry.getKey();
        int freq = entry.getValue();
        int complement = (k - rem) % k;

        // Special cases: remainder 0 or, when k is even, remainder k/2
        if (rem == 0 || (k % 2 == 0 && rem == k / 2)) {
            if (freq % 2 != 0) {
                return false;
            }
        } else {
            int compFreq = count.getOrDefault(complement, 0);
            if (freq != compFreq) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        int comp = k - r;
        if (r == comp) { // k even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[comp]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    if (count[0] % 2 != 0) return false;
    if (k % 2 == 0 && count[k / 2] % 2 != 0) return false;
    int upper = k / 2;
    if (k % 2 == 0) upper--; // exclude k/2 case already checked
    for (int r = 1; r <= upper; r++) {
        if (count[r] != count[k - r]) return false;
    }
    return true;
}

