private int dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] hasApple) {
    visited[node] = true;
    int total = 0;
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            int time = dfs(nei, graph, visited, hasApple);
            if (time > 0 || hasApple[nei]) {
                total += time + 2;
            }
        }
    }
    return total;
}

