public String sortString(String s) {
    int[] freq = new int[65536];
    for (char c : s.toCharArray()) freq[c]++;

    int remaining = s.length();
    StringBuilder result = new StringBuilder(remaining);

    while (remaining > 0) {
        // Increasing sequence
        int current = -1;
        for (int i = 0; i < 65536; i++) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
                remaining--;
                current = i;
                break;
            }
        }
        if (current == -1) break; // no characters left

        while (true) {
            int next = -1;
            for (int i = current + 1; i < 65536; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) next);
            freq[next]--;
            remaining--;
            current = next;
        }

        // Decreasing sequence
        current = -1;
        for (int i = 65535; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
                remaining--;
                current = i;
                break;
            }
        }
        if (current == -1) break; // no characters left

        while (true) {
            int next = -1;
            for (int i = current - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) next);
            freq[next]--;
            remaining--;
            current = next;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase: pick the smallest remaining character
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        sb.append(last);
        if (entry.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue() - 1);
        }

        // Continue ascending while possible
        while (true) {
            java.util.Map.Entry<Character, Integer> next = map.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            sb.append(last);
            if (next.getValue() == 1) {
                map.remove(last);
            } else {
                map.put(last, next.getValue() - 1);
            }
        }

        if (map.isEmpty()) break;

        // Descending phase: pick the largest remaining character
        java.util.Map.Entry<Character, Integer> lastEntry = map.lastEntry();
        char lastDown = lastEntry.getKey();
        sb.append(lastDown);
        if (lastEntry.getValue() == 1) {
            map.remove(lastDown);
        } else {
            map.put(lastDown, lastEntry.getValue() - 1);
        }

        // Continue descending while possible
        while (true) {
            java.util.Map.Entry<Character, Integer> prev = map.lowerEntry(lastDown);
            if (prev == null) break;
            lastDown = prev.getKey();
            sb.append(lastDown);
            if (prev.getValue() == 1) {
                map.remove(lastDown);
            } else {
                map.put(lastDown, prev.getValue() - 1);
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int num : nums) total += num;
    int half = n / 2;
    @SuppressWarnings("unchecked")
    ArrayList<HashSet<Integer>> dp = new ArrayList<>(half + 1);
    for (int i = 0; i <= half; i++) dp.add(new HashSet<>());
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = Math.min(half, dp.size() - 1); k >= 1; k--) {
            if (dp.get(k - 1).isEmpty()) continue;
            int target = total * k / n;
            if (total * k % n != 0) continue;
            for (int s : dp.get(k - 1)) {
                int newSum = s + num;
                if (newSum == target) return true;
                dp.get(k).add(newSum);
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int totalSum = 0;
    for (int v : nums) totalSum += v;

    // dp[k] holds all possible sums of subsets with size k
    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new Set[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        // traverse descending to avoid using the same element multiple times
        for (int k = n; k >= 1; k--) {
            if (dp[k - 1] == null) continue;
            if (dp[k] == null) dp[k] = new HashSet<>();
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((long) totalSum * k % n != 0) continue; // average can't be integer
        int target = (int) (((long) totalSum * k) / n);
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;
    int mid = n / 2;
    int leftSize = mid;
    int rightSize = n - mid;
    List<Set<Integer>> leftSets = new ArrayList<>(leftSize + 1);
    List<Set<Integer>> rightSets = new ArrayList<>(rightSize + 1);
    for (int i = 0; i <= leftSize; i++) leftSets.add(new HashSet<>());
    for (int i = 0; i <= rightSize; i++) rightSets.add(new HashSet<>());
    // Enumerate subsets of left part
    int leftMaskCount = 1 << leftSize;
    for (int mask = 0; mask < leftMaskCount; mask++) {
        int cnt = 0;
        int sum = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                cnt++;
                sum += nums[i];
            }
        }
        leftSets.get(cnt).add(sum);
    }
    // Enumerate subsets of right part
    int rightMaskCount = 1 << rightSize;
    for (int mask = 0; mask < rightMaskCount; mask++) {
        int cnt = 0;
        int sum = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                cnt++;
                sum += nums[mid + i];
            }
        }
        rightSets.get(cnt).add(sum);
    }
    // Check for each possible subset size
    for (int k = 1; k < n; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        int lMin = Math.max(0, k - rightSize);
        int lMax = Math.min(k, leftSize);
        for (int l = lMin; l <= lMax; l++) {
            int r = k - l;
            Set<Integer> leftSet = leftSets.get(l);
            Set<Integer> rightSet = rightSets.get(r);
            for (int leftSum : leftSet) {
                int need = target - leftSum;
                if (rightSet.contains(need)) return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Sets to keep possible sums for each subset size
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sums = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sums[i] = new HashSet<>();
    }
    sums[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the current num multiple times
        for (int k = Math.min(n, n) - 1; k >= 0; k--) {
            if (sums[k].isEmpty()) continue;
            for (int s : sums[k]) {
                sums[k + 1].add(s + num);
            }
        }
    }
    // Check for a split with equal average
    for (int k = 1; k <= n / 2; k++) {
        // Check if average can be integer
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (sums[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;
    // dp[k][s] = true if we can pick k elements with sum s
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k backwards to avoid reuse of same element
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = cost[0];          // cost to reach step 0
    int prev1 = cost[1];          // cost to reach step 1

    for (int i = 2; i < n; i++) {
        int cur = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = cur;
    }

    return Math.min(prev1, prev2); // min cost to reach the top from last two steps
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev1 = 0; // dp[i-1]
    int prev2 = 0; // dp[i-2]
    for (int i = 2; i <= n; i++) {
        int cost1 = prev1 + cost[i - 1];
        int cost2 = prev2 + cost[i - 2];
        int curr = Math.min(cost1, cost2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp[i] represents the minimal cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

