public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int maskLimit = total - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        seen[mask] = true;
    }
    for (boolean v : seen) {
        if (!v) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k; // 2^k
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    // initial window
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k <= 0) return false;
    int total = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1; // mask for k bits
    int curr = 0;
    int seenCount = 0;
    for (int i = 0; i < s.length(); i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                seenCount++;
                if (seenCount == total) return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;
    int required = 1 << k;  // 2^k
    boolean[] seen = new boolean[required];
    int mask = required - 1; // keep only k bits
    int hash = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        hash = ((hash << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[hash]) {
                seen[hash] = true;
                count++;
                if (count == required) return true; // early exit
            }
        }
    }
    return count == required;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int val = 0;
    int mask = totalCodes - 1;
    int len = s.length();
    for (int i = 0; i < len; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    if (sentence == null || searchWord == null) {
        return -1;
