public int minInsertions(String s) {
    int ans = 0;      // Number of insertions needed for unmatched ')'
    int open = 0;     // Current count of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else { // c == ')'
            if (open > 0) {
                open--;
            } else {
                ans++; // Insert a '(' before this ')'
            }
        }
    }
    // Each unmatched '(' still needs one ')' to balance
    ans += open;
    return ans;
}

public int minInsertions(String s) {
    int left = 0;   // Number of unmatched '('
    int ans = 0;    // Number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            left++;
        } else { // c == ')'
            if (left == 0) {
                // Need an opening bracket before this ')'
                ans++;
            } else {
                left--; // Match this ')' with an unmatched '('
            }
        }
    }
    // Any remaining unmatched '(' need a ')' each
    ans += left;
    return ans;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // insert a matching '(' before this ')'
                balance++;       // account for the inserted '('
            }
            balance--; // consume the closing bracket
        }
    }
    // Any remaining unmatched '(' require closing brackets
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    int need = 0; // number of unmatched '(' that need a ')'
    int insertions = 0; // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else { // c == ')'
            if (need == 0) {
                // we need a '(' before this ')'
                insertions++;
                // after inserting '(', we now have one unmatched '('
                need = 1;
            } else {
                need--; // match one '(' with this ')'
            }
        }
    }
    // After processing all characters, each remaining '(' needs a ')'
    // For an even number of unmatched '(' we need that many ')'
    // For an odd number, we need that many ')' plus an additional '(' before
    // So the remaining needed ')' are need / 2 + need % 2
    insertions += need / 2 + need % 2;
    return insertions;
}

public int minInsertions(String s) {
    int balance = 0;
    int additions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                additions++; // insert '(' before this ')'
            }
        }
    }
    return additions + balance; // add ')' for unmatched '('
}

public int minOperations(int n) {
    long totalDiff = 0;
    for (int i = 0; i < n; i++) {
        long value = 2L * i + 1;
        totalDiff += Math.abs(value - n);
    }
    return (int) (totalDiff / 2);
}

public int minOperations(int n) {
    int start = (n + 1) / 2;           // first index with value > n
    int m = n - start;                 // number of such indices
    return start * m;                  // minimal number of operations
}

public int minOperations(int n) {
    int L = (n + 1) / 2;
    return L * (n - L);
}

public int minOperations(int n) {
    int target = n;
    int ops = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        int diff = val - target;
        if (diff > 0) {
            ops += diff;
        }
    }
    return ops;
}

public int minOperations(int n) {
    return (int)((long)n * n / 4);
}

