public int maxAbsoluteSum(int[] nums) {
    long maxEnding = 0, maxSum = Long.MIN_VALUE;
    long minEnding = 0, minSum = Long.MAX_VALUE;
    for (int num : nums) {
        maxEnding = Math.max(num, maxEnding + num);
        maxSum = Math.max(maxSum, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minSum = Math.min(minSum, minEnding);
    }
    long result = Math.max(Math.abs(maxSum), Math.abs(minSum));
    return (int) result;
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    int maxEnding = nums[0];
    int maxOverall = nums[0];
    int minEnding = nums[0];
    int minOverall = nums[0];
    for (int i = 1; i < nums.length; i++) {
        maxEnding = Math.max(nums[i], maxEnding + nums[i]);
        maxOverall = Math.max(maxOverall, maxEnding);
        minEnding = Math.min(nums[i], minEnding + nums[i]);
        minOverall = Math.min(minOverall, minEnding);
    }
    return Math.max(maxOverall, Math.abs(minOverall));
}

