        curMin = Math.min(val, curMin + val);
        minSum = Math.min(minSum, curMin);
    }
    int absMax = Math.abs(maxSum);
    int absMin = Math.abs(minSum);
    return Math.max(absMax, absMin);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    int[] fibs = new int[50];
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) break;
        fibs[size++] = (int) next;
    }
    int count = 0;
    int remain = k;
    for (int i = size - 1; i >= 0; i--) {
        if (remain >= fibs[i]) {
            remain -= fibs[i];
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int n = fibs.size();
        int next = fibs.get(n - 1) + fibs.get(n - 2);
        if (next > k) break;
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int maxSize = 50;
    int[] fib = new int[maxSize];
    fib[0] = 1;
    fib[1] = 1;
    int fibCount = 2;
    while (true) {
        int next = fib[fibCount - 1] + fib[fibCount - 2];
        if (next > k) break;
        fib[fibCount] = next;
        fibCount++;
    }
    int count = 0;
    int remaining = k;
    for (int i = fibCount - 1; i >= 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
            if (remaining == 0) break;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k using the sequence 1, 2, 3, 5, ...
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // Greedy approach: repeatedly subtract the largest Fibonacci number <= remaining
    int remaining = k;
    int count = 0;
    while (remaining > 0) {
        int i = fibs.size() - 1;
        while (fibs.get(i) > remaining) {
            i--;
        }
        remaining -= fibs.get(i);
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is more than enough for k <= int max
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        long next = (long) fib[size - 1] + fib[size - 2];
        if (next > k) break;
        fib[size++] = (int) next;
    }

    int count = 0;
    int idx = size - 1;
    while (k > 0) {
        while (fib[idx] > k) idx--;
        k -= fib[idx];
        count++;
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int diff = n / i;
            if (diff != i) {
                large.add(diff);
            }
        }
    }
    int smallSize = small.size();
    int largeSize = large.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }
    // remaining k is for large factors (in ascending order)
    int indexInLarge = k - smallSize - 1;
    if (indexInLarge < largeSize) {
        // large list is currently in descending order, so reverse index
        return large.get(largeSize - 1 - indexInLarge);
    }
    return -1;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    // count small factors
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    // adjust k for large factors
    k -= small.size();
    for (int i = large.size() - 1; i >= 0; i--) {
        if (k == 1) {
            return large.get(i);
        }
        k--;
    }
    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> big = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int div = n / i;
            if (div != i) {
                big.add(div);
            }
        }
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>(small);
    for (int i = big.size() - 1; i >= 0; i--) {
        factors.add(big.get(i));
    }
    if (k - 1 < factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> factors = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                // We add the complementary factor to a temporary list to reverse later
                // to maintain ascending order
                factors.add(n / i);
            }
        }
    }
    // The above adds factors in a semi-sorted way: small factors first, then large factors unsorted
    // Instead, we should gather small and large separately
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    // Build final list: small ascending + large descending reversed to ascending
    for (Integer val : small) {
        factors.add(val);
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        factors.add(large.get(i));
    }
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    int sqrt = (int)Math.sqrt(n);
    int[] small = new int[sqrt];
    int smallSize = 0;
    int[] large = new int[sqrt];
    int largeSize = 0;
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small[smallSize++] = i;
            int div = n / i;
            if (div != i) {
                large[largeSize++] = div;
            }
        }
    }
    int total = smallSize + largeSize;
    if (k > total) return -1;
    if (k <= smallSize) return small[k - 1];
    int idxInLargeReversed = k - smallSize - 1;
    return large[largeSize - 1 - idxInLargeReversed];
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0 && Math.abs(c - stack.charAt(len - 1)) == 32) {
            stack.deleteCharAt(len - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Math.abs(last - c) == 32) {
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

