private void dfs(String s, int index, java.util.Set<String> used, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    if (count + (s.length() - index) <= max[0]) {
        return;
    }
    for (int len = 1; len <= s.length() - index; len++) {
        String sub = s.substring(index, index + len);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, index + len, used, count + 1, max);
            used.remove(sub);
        }
    }
}

