public String getSmallestString(int n, int k) {
    int extra = k - n;
    char[] chars = new char[n];
    Arrays.fill(chars, 'a');
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int add = Math.min(25, extra);
        chars[i] += add;
        extra -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    if (k < n || k > 26 * n) {
        return "";
    }
    int remaining = k - n; // the extra value to distribute over 'a's
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Ensure k is within the valid range for n characters
    if (k < n || k > 26 * n) {
        return ""; // or throw an exception if preferred
    }
    int remaining = k - n; // additional value needed beyond all 'a's
    char[] chars = new char[n];
    // Initially fill with 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    // Distribute the remaining value from the end towards the beginning
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // max increment per position
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    java.util.Arrays.fill(res, 'a');
    int diff = k - n;
    int i = n - 1;
    while (diff > 0 && i >= 0) {
        int add = Math.min(25, diff);
        res[i] = (char) (res[i] + add);
        diff -= add;
        i--;
    }
    return new String(res);
}

public String getSmallestString(int n, int k) {
    // Base string with all 'a's
    char[] s = new char[n];
    for (int i = 0; i < n; i++) {
        s[i] = 'a';
    }
    // Total value needed minus the base sum (n)
    int extra = k - n;
    // Distribute extra value from the end towards the start
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int inc = Math.min(25, extra); // maximum increment at one position
        s[i] = (char) ('a' + inc);
        extra -= inc;
    }
    return new String(s);
}

