public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        result |= (sum % 3) << i;
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos = twos | (ones & num);
        ones = ones ^ num;
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

