        int common = ~(ones & twos);
        ones &= common;
        twos &= common;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update twos with bits that have appeared twice
        twos |= ones & num;
        // Update ones with bits that have appeared an odd number of times
        ones ^= num;
        // Find bits that have appeared three times
        int commonMask = ~(ones & twos);
        // Remove bits that have appeared three times from ones and twos
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Include 0 separately if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with numbers 1-9 as starting points
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add((int) num);
        }

        int lastDigit = (int) (num % 10);

        long next1 = num * 10 + (lastDigit - 1);
        long next2 = num * 10 + (lastDigit + 1);

        if (lastDigit > 0 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit < 9 && next2 <= high) {
            queue.offer(next2);
        }
    }

    Collections.sort(result);
    return result;
}

