public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long factor = 1;
    long count = 0;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

