public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;
    int m = mat.length, n = mat[0].length;
    int[][][] dp = new int[4][m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                dp[0][i][j] = dp[1][i][j] = dp[2][i][j] = dp[3][i][j] = 0;
                continue;
            }
            dp[0][i][j] = (j > 0) ? dp[0][i][j - 1] + 1 : 1;             // horizontal
            dp[1][i][j] = (i > 0) ? dp[1][i - 1][j] + 1 : 1;             // vertical
            dp[2][i][j] = (i > 0 && j > 0) ? dp[2][i - 1][j - 1] + 1 : 1; // diagonal
            dp[3][i][j] = (i > 0 && j + 1 < n) ? dp[3][i - 1][j + 1] + 1 : 1; // anti-diagonal
            int current = Math.max(Math.max(dp[0][i][j], dp[1][i][j]),
                                   Math.max(dp[2][i][j], dp[3][i][j]));
            if (current > max) max = current;
        }
    }
    return max;
}

