private static void dfs(int[] A, boolean[] used, int depth, int lastVal, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue; // skip duplicates
        if (depth > 0 && !isPerfectSquare(lastVal + A[i])) continue;
        used[i] = true;
        dfs(A, used, depth + 1, A[i], count);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int sum) {
    int r = (int) Math.sqrt(sum);
    return r * r == sum;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute adjacency by indices
    List<int[]> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        int[] list = new int[n];
        int sz = 0;
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare(A[i] + A[j])) {
                list[sz++] = j;
            }
        }
        int[] res = new int[sz];
        System.arraycopy(list, 0, res, 0, sz);
        adj.add(res);
    }
    // Sort A to handle duplicates
    int[] sorted = A.clone();
    Arrays.sort(sorted);
    // Map sorted indices to original indices? Simpler: work on sorted values with count duplicates strategy.
    // We'll use DFS on indices of sorted array, adjacency recomputed on sorted indices.
    int[][] adjSorted = new int[n][];
    for (int i = 0; i < n; i++) {
        int[] list = new int[n];
        int sz = 0;
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare(sorted[i] + sorted[j])) {
                list[sz++] = j;
            }
        }
        int[] res = new int[sz];
        System.arraycopy(list, 0, res, 0, sz);
        adjSorted[i] = res;
    }
    long[] memo = new long[1 << n];
    Arrays.fill(memo, -1L);
    long result = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && sorted[i] == sorted[i - 1] && ((0 & (1 << (i - 1))) == 0)) {
            // skip duplicate starting positions
            continue;
        }
        result += dfs(1 << i, i, sorted, adjSorted, memo);
    }
    return (int) result;
}

private static long dfs(int mask, int last, int[] sorted, int[][] adj, long[] memo) {
    if (mask == (1 << sorted.length) - 1) return 1L;
    if (memo[mask] != -1L) return memo[mask];
    long sum = 0;
    for (int next : adj[last]) {
        if ((mask & (1 << next)) == 0) {
            // skip duplicates
            if (next > 0 && sorted[next] == sorted[next - 1] && (mask & (1 << (next - 1))) == 0) {
                continue;
            }
            sum += dfs(mask | (1 << next), next, sorted, adj, memo);
        }
    }
    memo[mask] = sum;
    return sum;
}

