public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort to handle duplicates conveniently
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);
    // Precompute perfect squares up to max possible sum
    int maxVal = sorted[n - 1];
    int maxSum = 2 * maxVal;
    int maxRoot = (int) Math.sqrt(maxSum) + 1;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int r = 0; r <= maxRoot; r++) {
        int s = r * r;
        if (s <= maxSum) isSquare[s] = true;
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    // Initialize starting positions
    for (int i = 0; i < n; i++) {
        // skip duplicates: only start with the first occurrence of each value
        if (i > 0 && sorted[i] == sorted[i - 1]) continue;
        int mask = 1 << i;
        dp[mask][i] = 1;
    }
    // DP over masks
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            // try to append next element j
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue; // already used
                // skip duplicates: only use the first unused occurrence among equal values
                if (j > 0 && sorted[j] == sorted[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                if (isSquare[sorted[last] + sorted[j]]) {
                    int nextMask = mask | (1 << j);
                    dp[nextMask][j] += cur;
                }
            }
        }
    }
    long result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && curHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

