public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    char[] arr = s.toCharArray();
    int len = arr.length;
    int i = len - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
    // reverse the subarray from i+1 to end
    int left = i + 1, right = len - 1;
    while (left < right) {
        char t = arr[left];
        arr[left] = arr[right];
        arr[right] = t;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(arr));
    } catch (NumberFormatException e) {
        return -1; // overflow case
    }
}

