}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array of its digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the longest non-increasing suffix
    int i = len - 1;
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }

    // If the entire array is non-increasing, no larger permutation exists
    if (i == 0) {
        return -1;
    }

    // Find the rightmost successor to the pivot
    int j = len - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }

    // Swap the pivot with its successor
    char temp = digits[i - 1];
    digits[i - 1] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at position i
    int left = i, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to an integer
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1; // Overflow, cannot represent in int
    }
    return (int) result;
}

