public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    String[][] pairs = {{"0", "0"}, {"1", "1"}, {"6", "9"}, {"8", "8"}, {"9", "6"}};
    List<String> prev = new ArrayList<>();
    prev.add("");
    for (int len = 2; len <= n; len++) {
        List<String> next = new ArrayList<>();
        for (String s : prev) {
            for (String[] pair : pairs) {
                String left = pair[0];
                String right = pair[1];
                if (len == n && left.equals("0")) {
                    continue; // avoid leading zeros for numbers longer than 1 digit
                }
                next.add(left + s + right);
            }
        }
        prev = next;
    }
    return prev;
}

