private static List<String> build(int len, boolean outer) {
    if (len == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (len == 1) {
        return List.of("0", "1", "8");
    }
    List<String> mid = build(len - 2, false);
    List<String> res = new ArrayList<>();
    char[][] pairs;
    if (outer) {
        pairs = new char[][]{{'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    } else {
        pairs = new char[][]{{'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'}};
    }
    for (char[] pair : pairs) {
        for (String s : mid) {
            res.add(pair[0] + s + pair[1]);
        }
    }
    return res;
}

