public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Using cross product to check collinearity
    return (x2 - x1) * (y3 - y1) != (x3 - x1) * (y2 - y1);
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1 == null || p2 == null || p3 == null || p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }
    // Check for duplicate points
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }
    // Calculate the area (twice the signed area) using determinant
    int det = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1]);
    return det != 0;
}

