public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int current, int n, List<Integer> res) {
    res.add(current);
    int next = current * 10;
    while (next <= n) {
        dfs(next, n, res);
        next = next / 10 + 1;
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else if (current % 10 != 9 && current + 1 <= n) {
            current++;
        } else {
            while (current / 10 > 0 && (current % 10 == 9 || current + 1 > n)) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

